package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_EmptyString() throws NumberFormatException {
        NumberUtils.createNumber("");
    }

    @Test
    public void testCreateNumber_DoubleDashProtection() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hexadecimal() throws NumberFormatException {
        // Assuming createInteger handles hex
        assertEquals(Integer.valueOf(16), NumberUtils.createNumber("0x10"));
        assertEquals(Integer.valueOf(-16), NumberUtils.createNumber("-0x10"));
    }

    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123"));
        assertEquals(new BigInteger("12345678901234567890"), NumberUtils.createNumber("12345678901234567890"));
    }

    @Test
    public void testCreateNumber_DecimalTypes() throws NumberFormatException {
        assertEquals(new BigDecimal("123.45"), NumberUtils.createNumber("123.45"));
        assertEquals(123.45F, NumberUtils.createNumber("123.45F").floatValue(), 0.001);
        assertEquals(123.45D, NumberUtils.createNumber("123.45D").doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_ScientificNotation() throws NumberFormatException {
        // Without suffix
        assertEquals(new BigDecimal("1.2e3"), NumberUtils.createNumber("1.2e3"));
        // With suffix
        assertEquals(1.2e3F, NumberUtils.createNumber("1.2e3f").floatValue(), 0.001);
        assertEquals(1.2e3D, NumberUtils.createNumber("1.2e3d").doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_LongSuffix() throws NumberFormatException {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123l"));
        assertEquals(new BigInteger("12345678901234567890"), NumberUtils.createNumber("12345678901234567890L"));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidLongSuffix() throws NumberFormatException {
        NumberUtils.createNumber("12.3L");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExpPos() throws NumberFormatException {
        // Trigger: if (expPos < decPos)
        NumberUtils.createNumber("1e.5");
    }

    @Test
    public void testCreateNumber_FloatPrecisionFallthrough() throws NumberFormatException {
        // A number that is too large for Float, should fall through to Double or BigDecimal
        // Using a very large number that fits in Double but not Float
        String largeVal = "1e40"; 
        Number n = NumberUtils.createNumber(largeVal);
        assertTrue(n instanceof Double || n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_AllZerosCase() throws NumberFormatException {
        // Testing "allZeros" logic for precision check
        // 0.000... with suffix
        assertEquals(0.0F, NumberUtils.createNumber("0.0e0f").floatValue(), 0.0);
        assertEquals(0.0D, NumberUtils.createNumber("0.0e0d").doubleValue(), 0.0);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() throws NumberFormatException {
        NumberUtils.createNumber("123z");
    }

    @Test
    public void testCreateNumber_ComplexScientificWithSuffix() throws NumberFormatException {
        // Test suffix logic where exp is extracted
        // val.substring(expPos + 1, val.length() - 1)
        assertEquals(1230.0F, NumberUtils.createNumber("1.23e1f").floatValue(), 0.001);
    }

    @Test
    public void testCreateNumber_NegativeInteger() throws NumberFormatException {
        assertEquals(Integer.valueOf(-123), NumberUtils.createNumber("-123"));
    }

    @Test
    public void testCreateNumber_BigIntegerFallthrough() throws NumberFormatException {
        // Test the case where it's not an int or long, but a BigInteger
        String big = "999999999999999999999999999999";
        Number n = NumberUtils.createNumber(big);
        assertTrue(n instanceof BigInteger);
    }
}
